// Outer UAE boundary of the 10x10 matrix: every edge where an in-UAE cell
// touches an outside-UAE cell or the matrix edge (10 units per cell).
const UAE_MATRIX_BOUNDARY_PATH = (() => {
  const inside = (r: number, c: number) => {
    if (r < 0 || c < 0 || r > 9 || c > 9) return false;
    return !GRID_MATRIX_CELLS[r * 10 + c].isOutsideUae;
  };
  const segs: string[] = [];
  for (let r = 0; r < 10; r++) {
    for (let c = 0; c < 10; c++) {
      if (!inside(r, c)) continue;
      const x = c * 10;
      const y = r * 10;
      if (!inside(r - 1, c)) segs.push(`M${x} ${y}H${x + 10}`);
      if (!inside(r + 1, c)) segs.push(`M${x} ${y + 10}H${x + 10}`);
      if (!inside(r, c - 1)) segs.push(`M${x} ${y}V${y + 10}`);
      if (!inside(r, c + 1)) segs.push(`M${x + 10} ${y}V${y + 10}`);
    }
  }
  return segs.join("");
})();

